      "name": "Catatonia associated with another mental disorder",
      "properties": {
        "subtype": "",
        "course_requirements": "Acute episodes typically develop rapidly within hours or days; most commonly resolve within 4 weeks, some remit spontaneously within hours, may persist for months or years; recurrent episodes of several weeks duration; persistent catatonia associated with Neurodevelopmental Disorders or Schizophrenia.",
        "comorbidity_types": "Schizophrenia or Other Primary Psychotic Disorders, Mood Disorders, Neurodevelopmental Disorders (especially Autism Spectrum Disorder), Post-Traumatic Stress Disorder, Depressive Disorders",
        "prognosis_factors": "",
