      "properties": {
        "core_features": "Psychomotor retardation in Depressive Episode",
        "key_differentiation_points": "In the presence of a Depressive or Mixed Episode, an additional diagnosis of Catatonia Associated with Another Mental Disorder is appropriate if symptoms of increased psychomotor activity or abnormal psychomotor activity are also present.",
        "misdiagnosis_risk": ""
      }
    },
    {
      "id": "D3",
