      "name": "psychomotor agitation in Depressive, Manic or Mixed Episode",
      "properties": {
        "core_features": "Psychomotor agitation in a Mood Episode",
        "key_differentiation_points": "In the presence of a Mood Episode, an additional diagnosis of Catatonia Associated with Another Mental Disorder is only appropriate if symptoms of decreased psychomotor activity or abnormal psychomotor activity are also present.",
        "misdiagnosis_risk": ""
      }
    },
    {
      "id": "D4",
      "label": "Disease",
      "name": "Neuroleptic Malignant Syndrome",
      "properties": {
        "core_features": "high fever, muscle stiffness, altered mental status, and autonomic dysfunction",
        "key_differentiation_points": "Diagnosis is based on the clinical judgment that exposure to an antipsychotic medication or other dopamine receptor blocking agents is the cause of the symptoms. Made based on timing of symptoms in relation to medication use, prior history of multiple episodes of Catatonia, and presence of certain medical complications (hyperkalemia, liver or kidney failure).",
        "misdiagnosis_risk": "Distinction can be difficult because many individuals who develop Catatonia take antipsychotic medication."
      }
    },
    {
      "id": "D5",
      "label": "Disease",
      "name": "Serotonin Syndrome",
      "properties": {
        "core_features": "agitation or restlessness and muscle rigidity as well as autonomic disturbances such as high fever and tachycardia",
        "key_differentiation_points": "Diagnosis involves clinical judgment that exposure to a serotonergic medication or an interaction between serotonergic medications is the cause. More likely to present with tremor, hyperactive muscle reflexes (including clonus) and nystagmus than Catatonia.",
        "misdiagnosis_risk": ""
      }
    },
    {
      "id": "D6",
      "label": "Disease",
      "name": "Malingering or Factitious Disorder",
      "properties": {
        "core_features": "evidence of feigning of symptoms",
        "key_differentiation_points": "Evidence for feigning often includes the observation that the symptoms occur only when the person is being watched. However, disturbances of volition in Catatonia (e.g., negativism) may only become apparent during social interactions, which should not by itself be interpreted as evidence of feigning.",
        "misdiagnosis_risk": ""
      }
    },
