      "id": "DC1",
      "label": "Diagnostic Criteria",
      "name": "General diagnostic requirements for Catatonia",
      "properties": {
        "required_core_symptoms": "The general diagnostic requirements for Catatonia are met."
      }
    },
    {
      "id": "DC2",
      "label": "Diagnostic Criteria",
      "name": "Timing of symptom onset",
      "properties": {
        "required_core_symptoms": "The catatonic symptoms develop during or soon after intoxication with or withdrawal from a specified psychoactive substance or the use of a medication."
      }
    },
    {
      "id": "DC3",
      "label": "Diagnostic Criteria",
      "name": "Intensity or duration of symptoms",
      "properties": {
        "required_core_symptoms": "The intensity or duration of the catatonic symptoms is substantially in excess of similar symptoms that are characteristic of intoxication or withdrawal due to the specified substance."
      }
    },
    {
      "id": "DC4",
      "label": "Diagnostic Criteria",
      "name": "Substance capability",
      "properties": {
        "required_core_symptoms": "The specified substance, as well as the amount and duration of its use, must be capable of producing catatonic symptoms."
      }
    },
    {
      "id": "DC5",
      "label": "Diagnostic Criteria",
      "name": "Exclusion of other disorders",
      "properties": {
        "exclusion_details": "The symptoms are not fully accounted for by Delirium, another mental disorder (e.g., Schizophrenia or Other Primary Psychotic Disorder, a Mood Disorder, Autism Spectrum Disorder), or to be the direct pathophysiological consequence of a medical condition."
      }
    },
    {
      "id": "DC6",
      "label": "Diagnostic Criteria",
      "name": "Severity of symptoms",
      "properties": {
        "functional_impairment_requirements": "The symptoms are sufficiently severe to be a specific focus of clinical attention."
      }
    },
    {
      "id": "D2",
      "label": "Disease",
      "name": "non-substance induced Catatonia",
      "properties": {
        "key_differentiation_points": "catatonic symptoms preceding the onset of the substance use, the symptoms persisting for a substantial period of time after cessation of the substance or medication use or withdrawal, or other evidence of a pre-existing mental disorder"
      }
    },
    {
      "id": "D3",
      "label": "Disease",
      "name": "Delirium Due to Diseases Classified Elsewhere",
      "properties": {
        "key_differentiation_points": "Distinguished primarily by the disturbance of attention, awareness and arousal, as well as impairment in other cognitive domains, that characterize Delirium and are not features of Catatonia"
      }
    },
    {
      "id": "D4",
      "label": "Disease",
      "name": "Neuroleptic Malignant Syndrome",
      "properties": {
        "key_differentiation_points": "Based on the timing of the symptoms in relation to medication use, prior history of multiple episodes of Catatonia, and sometimes the presence of certain medical complications that are not characteristic of Catatonia, such as hyperkalemia or liver or kidney failure."
      }
    },
    {
      "id": "D5",
      "label": "Disease",
      "name": "Serotonin Syndrome",
      "properties": {
        "key_differentiation_points": "More likely to present with tremor, hyperactive muscle reflexes (including clonus) and nystagmus than Catatonia."
      }
    },
    {
      "id": "D6",
      "label": "Disease",
      "name": "Malingering or Factitious Disorder",
      "properties": {
        "key_differentiation_points": "Diagnosed based on evidence of feigning of symptoms, which often includes the observation that the symptoms occur only when the person is being watched."
      }
    },
