    {
      "id": "D1",
      "label": "Disease",
      "name": "Body integrity dysphoria",
      "properties": {
        "course_requirements": "The typical course is for the intensity of the desire to become disabled and consequent functional impairment to wax and wane.",
        "icdcode": "6C21",
        "coding_system": "ICD-11-MMS",
        "icd_release": "2025-01",
        "icd_uri": "http://id.who.int/icd/release/11/2025-01/mms/256572629"
      }
    },
    {
      "id": "S1",
      "label": "Symptom",
      "name": "Intense and persistent desire to become physically disabled in a significant way",
      "properties": {
        "description": "Desire to become physically disabled (e.g., a major limb amputation, paraplegia, blindness)",
        "occurrence_frequency": "persistent"
      }
    },
    {
      "id": "S2",
      "label": "Symptom",
      "name": "Persistent discomfort or intense negative feelings about one’s current body configuration or functioning",
      "properties": {
        "occurrence_frequency": "persistent"
      }
    },
    {
      "id": "S3",
      "label": "Symptom",
      "name": "Preoccupation with the desire to be disabled",
      "properties": {
        "description": "Results in significant impairment in personal, family, social, educational, occupational, or other important areas of functioning"
      }
    },
    {
      "id": "S4",
      "label": "Symptom",
      "name": "Attempts to actually become disabled through self-injury",
      "properties": {
        "description": "Resulted in the person putting their health or life in significant jeopardy"
      }
    },
    {
      "id": "S5",
      "label": "Symptom",
      "name": "'Pretending' or simulation behaviour",
      "properties": {
        "description": "Binding one’s leg to simulate being a person with a limb amputation, or using a wheelchair or crutches, usually done in secret"
      }
    },
    {
      "id": "S6",
      "label": "Symptom",
      "name": "Sexual component to their desire",
      "properties": {
        "description": "Sexually attracted to individuals with certain disabilities or being intensely sexually aroused at thought of being disabled"
      }
    },
    {
      "id": "S7",
      "label": "Symptom",
      "name": "Shame about the desire to be disabled",
      "properties": {
        "description": "Kept as a closely guarded secret because of a fear of being rejected or thought to be ‘crazy’ by others"
      }
    },
    {
      "id": "DC1",
      "label": "Diagnostic Criteria",
      "name": "Essential (Required) Features",
      "properties": {
        "required_core_symptoms": "An intense and persistent desire to become physically disabled in a significant way accompanied by persistent discomfort or intense negative feelings about one’s current body configuration or functioning. Onset by early adolescence.",
        "functional_impairment_requirements": "Significant impairment in personal, family, social, educational, occupational, or other important areas of functioning, or putting health or life in significant jeopardy.",
        "exclusion_details": "Not better accounted for by another mental disorder, Malingering, Gender Incongruence, a Disease of the Nervous System, or another medical condition."
      }
    },
    {
      "id": "D2",
      "label": "Disease",
      "name": "Schizophrenia",
      "properties": {
        "key_differentiation_points": "Somatic delusions may involve the conviction that a part of the person’s body does not belong to them. Individuals with Body Integrity Dysphoria do not harbour false beliefs about external reality."
      }
    },
    {
      "id": "D3",
      "label": "Disease",
      "name": "Other Primary Psychotic Disorder",
      "properties": {
        "key_differentiation_points": "Somatic delusions may involve the conviction that a part of the person’s body does not belong to them."
      }
    },
    {
      "id": "D4",
      "label": "Disease",
      "name": "Obsessive-Compulsive Disorder",
      "properties": {
        "key_differentiation_points": "Characterized by repetitive and persistent thoughts, images, or urges that are experienced as intrusive and unwanted (ego-dystonic). In contrast, the repetitive thoughts in Body Integrity Dysphoria are ego-syntonic."
      }
    },
    {
      "id": "D5",
      "label": "Disease",
      "name": "Body Dysmorphic Disorder",
      "properties": {
        "key_differentiation_points": "Persistent preoccupations about a part of their body that they believe is defective or that their appearance overall is ugly. In contrast, individuals with Body Integrity Dysphoria are persistently preoccupied with a sense that the way their body is configured or functions is wrong, unnatural."
      }
    },
    {
      "id": "D6",
      "label": "Disease",
      "name": "Paraphilic Disorder Involving Solitary Behaviour or Consenting Individual",
      "properties": {
        "key_differentiation_points": "If the desire to acquire a disability occurs solely in connection with sexual arousal, Body Integrity Dysphoria should not be diagnosed."
      }
    },
    {
      "id": "D7",
      "label": "Disease",
      "name": "Factitious Disorder",
      "properties": {
        "key_differentiation_points": "Feign medical or psychological signs or symptoms in order to seek attention, especially from health providers and to assume the sick role. Individuals with Body Integrity Disorder typically shun medical attention."
      }
    },
    {
      "id": "D8",
      "label": "Disease",
      "name": "Malingering",
      "properties": {
        "key_differentiation_points": "Characterized by feigning of medical or psychological signs or symptoms for obvious external incentives (e.g., disability payments)."
      }
    },
    {
      "id": "D9",
      "label": "Disease",
      "name": "Diseases of the Nervous System",
      "properties": {
        "key_differentiation_points": "May cause symptoms that involve profound changes in the person’s attitude towards and experience of their own bodies (e.g., somatoparaphrenia)."
      }
    },
    {
      "id": "D10",
      "label": "Disease",
      "name": "Gender Incongruence",
      "properties": {}
    }
