      "name": "Hazardous Use of Opioids",
      "properties": {
        "core_features": "appreciably increases the risk of harmful physical or mental health consequences to the user or to others",
        "key_differentiation_points": "has not resulted in specific identifiable harm and therefore does not meet the diagnostic requirements for Episode of Harmful Use of Opioids",
        "misdiagnosis_risk": ""
      }
    },
