      "id": "DD1",
      "label": "Disease",
      "name": "Hazardous Use of Cocaine",
      "properties": {
        "core_features": "Appreciably increases the risk of harmful physical or mental health consequences to the user or to others.",
        "key_differentiation_points": "Has not resulted in specific identifiable harm and therefore does not meet the diagnostic requirements for Episode of Harmful Use of Cocaine.",
        "misdiagnosis_risk": ""
      }
    },
    {
