      "label": "Disease",
      "name": "Harmful Pattern of Use of Cocaine",
      "properties": {
        "core_features": "Harm to health is a result of a known episodic or continuous pattern of substance use.",
        "key_differentiation_points": "Substance use is generally considered to be following a pattern if there has been at least episodic or intermittent use over a period of at least 12 months.",
        "misdiagnosis_risk": ""
      }
    },
    {
      "id": "DD3",
      "label": "Disease",
      "name": "Cocaine Dependence",
      "properties": {
        "core_features": "Individuals use cocaine persistently despite harm and adverse consequences.",
        "key_differentiation_points": "Includes additional features of impaired ability to control use and increasing priority given to the substance use over other activities. Physiological features (e.g., tolerance) may also be present.",
        "misdiagnosis_risk": ""
      }
    },
    {
      "id": "DD4",
      "label": "Disease",
      "name": "Cocaine Intoxication",
      "properties": {
        "core_features": "Cocaine use that results in clinically significant transient cocaine-specific symptoms.",
        "key_differentiation_points": "Recovery from Cocaine Intoxication is generally complete and without physical or mental sequelae. If there is continuing damage or harm, Episode of Harmful Use of Cocaine may be assigned.",
        "misdiagnosis_risk": ""
      }
    },
    {
      "id": "DD5",
      "label": "Disease",
      "name": "Cocaine-Induced Mental Disorders",
      "properties": {
        "core_features": "Mental disorders associated with a single episode of cocaine use.",
        "key_differentiation_points": "If a Cocaine-Induced Mental Disorder has occurred as a form of harm resulting from a single episode of cocaine use, both Episode of Harmful Use of Cocaine and the relevant Cocaine-Induced Mental Disorder should be diagnosed.",
