    {
      "id": "E2",
      "label": "Symptom",
      "name": "Impaired control over cocaine use",
      "properties": {
        "description": "Impaired control over cocaine use (i.e., onset, frequency, intensity, duration, termination, context)"
      }
    },
    {
      "id": "E3",
      "label": "Symptom",
      "name": "Increasing precedence of cocaine use",
      "properties": {
        "description": "Increasing precedence of cocaine use over other aspects of life, including maintenance of health, and daily activities and responsibilities, such that cocaine use continues or escalates despite the occurrence of harm or negative consequences"
      }
    },
    {
      "id": "E4",
      "label": "Symptom",
      "name": "Physiological features indicative of neuroadaptation",
      "properties": {
        "description": "tolerance to the effects of cocaine or a need to use increasing amounts of cocaine to achieve the same effect; withdrawal symptoms following cessation or reduction in use of cocaine; or repeated use of cocaine or pharmacologically similar substances to prevent or alleviate withdrawal symptoms"
      }
    },
    {
      "id": "E5",
      "label": "Symptom",
      "name": "Subjective sensation of urge or craving",
      "properties": {
        "description": "A subjective sensation of urge or craving to use cocaine often, but not always, accompanies the Essential Features of Cocaine Dependence."
      }
    },
    {
      "id": "E6",
      "label": "Disease",
      "name": "Cocaine Intoxication",
      "properties": {
        "key_differentiation_points": "Episodic or continuous intoxication with cocaine is a typical feature of Cocaine Dependence, but is not an Essential Feature. Conversely, even if frequent and severe, Cocaine Intoxication alone is not a basis for a diagnosis of Cocaine Dependence."
      }
    },
    {
      "id": "E7",
      "label": "Disease",
      "name": "Harmful Use of Cocaine",
      "properties": {
        "key_differentiation_points": "In the absence of the Essential Features of Cocaine Dependence, a diagnosis of Harmful Use of Cocaine can be given when there has been demonstrable harm to the individual’s physical or mental health or that of others. Harmful Pattern of Use of Cocaine and Cocaine Dependence should not be diagnosed together."
      }
    },
    {
      "id": "E8",
      "label": "Disease",
      "name": "Cocaine Withdrawal",
      "properties": {
        "key_differentiation_points": "Many individuals with Cocaine Dependence develop Cocaine Withdrawal upon cessation or reduction in the amount of a cocaine consumed. In such cases, both Cocaine Dependence and Cocaine Withdrawal should be diagnosed. However, Cocaine Withdrawal can be diagnosed in the absence of a diagnosis of Cocaine Dependence."
      }
    },
    {
      "id": "E9",
      "label": "Disease",
      "name": "Cocaine-Induced Mental Disorders",
      "properties": {
        "key_differentiation_points": "The impact of repeated or continuous use of substances characteristic of Cocaine Dependence may include Cocaine-Induced Mental Disorders, in which case both Cocaine Dependence and the relevant Cocaine-Induced Mental Disorder should be diagnosed."
      }
    },
    {
      "id": "E10",
      "label": "Diagnostic Criteria",
      "name": "Diagnostic requirements for Cocaine Dependence",
      "properties": {
        "required_core_symptoms": "A pattern of recurrent episodic or continuous use of cocaine with evidence of impaired regulation of cocaine use that is manifested by two or more of the following: Impaired control over cocaine use; Increasing precedence of cocaine use; Physiological features indicative of neuroadaptation",
        "exclusion_details": "Harmful Pattern of Use of Cocaine and Cocaine Dependence should not be diagnosed together."
      }
    },
    {
      "id": "E11",
      "label": "Patient Information",
      "name": "Adolescents",
      "properties": {
        "age_group": "Adolescents",
        "special_conditions": "Substance Dependence may develop more rapidly during adolescence than is usual during adulthood. Tolerance to psychoactive substances may develop rapidly in adolescents and young adults, and decline equally rapidly when substance use ceases or is reduced."
      }
    },
    {
      "id": "E12",
      "label": "Patient Information",
      "name": "Older adults",
      "properties": {
        "age_group": "Older adults",
        "special_conditions": "Older adults often have reduced tolerance to substances."
      }
    },
    {
      "id": "E13",
      "label": "Patient Information",
      "name": "Women",
      "properties": {
        "special_conditions": "Women are less likely to be involved with the legal system in relation to substance use and therefore may be less likely to come to clinical attention than men. In clinical contexts, women may be reluctant to admit using substances due to prevailing social attitudes and proscriptions."
      }
    },
    {
      "id": "E14",
      "label": "Patient Information",
      "name": "Neonates",
      "properties": {
        "age_group": "Neonates",
        "special_conditions": "Withdrawal symptoms are well recognized in neonates born to women with Substance Dependence who have used psychoactive substances during pregnancy. However, the presence of a withdrawal state in a neonate should not be the sole basis for a diagnosis of Substance Dependence in the mother."
      }
    },
